"  useEffect(() => {
    localStorage.setItem('pos_current_shift', JSON.stringify(shift));
  }, [shift]);

  const [passcodeModal, setPasscodeModal] = useState({
    isOpen: false,
    title: '',
    requiredPermission: '',
    callback: null,
    pin: ''
  });

  const checkPermission = (path, callback) => {
    const posAccess = business?.staff_permissions?.pos_access;
    const role = String(business?.role || '').toLowerCase();
    const isSupervisor = role === 'brand_owner' || role === 'master_admin' || role.includes('admin') || role.includes('manager');

    if (!posAccess) {
      callback();
      return;
    }

    const parts = path.split('.');
    let allowed = posAccess;
    for (const part of parts) {
      allowed = allowed?.[part];
    }

    if (allowed === false && !isSupervisor) {
      toast.error("Access Denied: You do not have permission to perform this action.");
      return;
    }

    const passcodePath = path + '_passcode';
    let needsPasscode = posAccess;
    for (const part of passcodePath.split('.')) {
      needsPasscode = needsPasscode?.[part];
    }

    if (needsPasscode === true && !isSupervisor) {
      setPasscodeModal({
        isOpen: true,
        title: `Supervisor Authorization Required`,
        requiredPermission: path,
        callback: callback,
        pin: ''
      });
      return;
    }

    callback();
  };

  const isModuleAllowed = (moduleName) => {
    const role = String(business?.role || '').toLowerCase();
    const isSupervisor = role === 'brand_owner' || role === 'master_admin' || role.includes('admin') || role.includes('manager');
    if (isSupervisor) return true;

    const storeModules = business?.staff_permissions?.store_modules;
    if (!storeModules) return true;
    return storeModules[moduleName]?.visible !== false;
  };"
